<?php
$pageTitle=t('page_depreciation');$ws_id=(int)($_SESSION['workshop_id']??0);$can_depr=is_strict_admin()||has_permission('manage_inventory')||access_mode('inventory')==='editor';if(!$can_depr){showToast(t('دسترسی ندارید'),'error');redirect('index.php?page=dashboard');}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_asset'){
    $id=(int)$_POST['item_id'];$price=max(0,(float)$_POST['asset_purchase_price']);$date=to_gregorian($_POST['asset_purchase_date']??'');$life=max(0,(int)$_POST['useful_life_months']);
    $pdo->prepare("UPDATE inventory_items SET asset_purchase_price=?,asset_purchase_date=?,useful_life_months=? WHERE id=? AND workshop_id=?")->execute([$price,$date?:null,$life,$id,$ws_id]);operations_audit($pdo,(int)$_SESSION['user_id'],'asset_depreciation','inventory_item',$id,'قیمت '.$price.' عمر '.$life.' ماه');showToast(t('اطلاعات استهلاک ذخیره شد.'));redirect('index.php?page=inventory&tab=depreciation');
}
$assets=[];try{$st=$pdo->prepare("SELECT i.*,COALESCE((SELECT SUM(repair_cost) FROM inventory_transactions t WHERE t.item_id=i.id AND t.deleted_at IS NULL),0) repair_total,COALESCE((SELECT COUNT(*) FROM inventory_serials s WHERE s.item_id=i.id),0) serial_count FROM inventory_items i WHERE i.workshop_id=? AND i.status='active' ORDER BY i.name");$st->execute([$ws_id]);$assets=$st->fetchAll();}catch(Throwable $e){}
include 'includes/header.php';
?>
<div class="d-flex justify-between align-center mb-4 animate-in"><h2>📉 <?= t('page_depreciation') ?></h2></div>
<div class="tabs mb-4 animate-in inventory-tools-tabs"><a href="index.php?page=inventory&tab=stock" class="tab"><?= t('inv_stock') ?></a><a href="index.php?page=inventory&tab=active" class="tab"><?= t('خارج‌شده') ?></a><a href="index.php?page=inventory&tab=history" class="tab"><?= t('سابقه') ?></a><a href="index.php?page=inventory&tab=serials" class="tab">🔖 <?= t('سریال ابزار') ?></a><a href="index.php?page=inventory&tab=purchases" class="tab">🛒 <?= t('page_purchases') ?></a><a href="index.php?page=inventory&tab=depreciation" class="tab active">📉 <?= t('استهلاک') ?></a></div><div class="alert alert-info"><?= t('استهلاک خطی') ?>: <?= t('قیمت خرید') ?> ÷ <?= t('عمر مفید') ?> <?= t('sal_monthly') ?>. <?= t('هزینهٔ تعمیر') ?> <?= t('جداگانه') ?> <?= t('btn_show') ?> <?= t('داده') ?> <?= t('می‌شود') ?> <?= t('lea_to') ?> <?= t('تصمیم') ?> «<?= t('تعمیر') ?> <?= t('یا') ?> <?= t('خرید') ?> <?= t('مجدد') ?>» <?= t('ساده‌تر') ?> <?= t('باشد') ?>.</div>
<div class="card animate-in"><div class="table-container"><table><thead><tr><th><?= t('کالا') ?></th><th><?= t('سریال') ?></th><th><?= t('قیمت خرید') ?></th><th><?= t('wh_date') ?> <?= t('خرید') ?></th><th><?= t('عمر مفید') ?></th><th><?= t('استهلاک') ?> <?= t('sal_monthly') ?></th><th><?= t('استهلاک') ?> <?= t('lea_to') ?> <?= t('wh_today') ?></th><th><?= t('تعمیرات') ?></th><th><?= t('pet_balance') ?> <?= t('دفتری') ?></th><th></th></tr></thead><tbody><?php foreach($assets as $a):$price=(float)$a['asset_purchase_price'];$life=(int)$a['useful_life_months'];$months=($a['asset_purchase_date']&&$life>0)?max(0,(int)floor((time()-strtotime($a['asset_purchase_date']))/(30.44*86400))):0;$monthly=$life>0?$price/$life:0;$depr=min($price,$monthly*$months);$book=max(0,$price-$depr);?><tr><td><strong><?=htmlspecialchars($a['name'])?></strong></td><td><?=$a['serial_count']?></td><td><?=number_format($price)?> <?= t('ت') ?></td><td><?=$a['asset_purchase_date']?to_jalali($a['asset_purchase_date']):'—'?></td><td><?=$life?$life.' '.t('ماه'):'—'?></td><td><?=number_format($monthly)?> <?= t('ت') ?></td><td><?=number_format($depr)?> <?= t('ت') ?></td><td><?=number_format((float)$a['repair_total'])?> <?= t('ت') ?></td><td><?=number_format($book)?> <?= t('ت') ?></td><td><button class="btn btn-ghost btn-sm" onclick='editAsset(<?=js_arg($a)?>)'>✏️</button></td></tr><?php endforeach;?><?php if(empty($assets)):?><tr><td colspan="10" class="text-center text-muted"><?= t('کالایی نیست.') ?></td></tr><?php endif;?></tbody></table></div></div>
<div id="assetModal" class="modal-overlay hidden"><div class="modal glass-modal"><div class="modal-header"><h3 class="modal-title"><?= t('nav_settings') ?> <?= t('استهلاک') ?></h3><button class="modal-close" onclick="closeModal('assetModal')">✕</button></div><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="save_asset"><input type="hidden" name="item_id" id="assetId"><div class="modal-body"><p><?= t('کالا:') ?> <strong id="assetName"></strong></p><div class="form-group"><label class="form-label"><?= t('قیمت خرید') ?> (<?= t('sal_toman') ?>)</label><input type="number" name="asset_purchase_price" id="assetPrice" class="form-control" min="0"></div><div class="form-row"><div class="form-group"><label class="form-label"><?= t('wh_date') ?> <?= t('خرید') ?></label><input name="asset_purchase_date" id="assetDate" class="form-control jalali-date"></div><div class="form-group"><label class="form-label"><?= t('عمر مفید') ?> (<?= t('rep_month') ?>)</label><input type="number" name="useful_life_months" id="assetLife" class="form-control" min="0"></div></div></div><div class="modal-footer"><button class="btn btn-primary"><?= t('btn_save') ?></button></div></form></div></div><script>function editAsset(a){assetId.value=a.id;assetName.textContent=a.name;assetPrice.value=a.asset_purchase_price||0;assetDate.value=a.asset_purchase_date?toJalali(a.asset_purchase_date):'';assetLife.value=a.useful_life_months||0;openModal('assetModal');}</script><?php include 'includes/footer.php'; ?>
